package pl.atrop.powerguard.bcknd.meter.domain;
import jakarta.enterprise.context.ApplicationScoped; import jakarta.inject.Inject; import java.math.BigDecimal; import java.util.*; import pl.atrop.powerguard.bcknd.edge.domain.EdgesService;
@ApplicationScoped public class DomainMetersService implements MetersService {
 @Inject MetersRepository repository; @Inject EdgesService edges;
 public List<MeterConfiguration> findPublicMeters(){return repository.findAll().stream().filter(MeterConfiguration::enabled).toList();} public List<MeterConfiguration> findAll(){return repository.findAll();} public Optional<MeterConfiguration> findById(Integer id){return id==null?Optional.empty():repository.findById(id);}
 public Optional<MeterConfiguration> findByIdentity(String clientId,String siteId,String edgeId,String uniqueKey){return repository.findByIdentity(clientId,siteId,edgeId,uniqueKey);} public Optional<MeterConfiguration> findByLegacyIdentity(String siteId,String edgeId,String uniqueKey){return repository.findByLegacyIdentity(siteId,edgeId,uniqueKey);}
 public Optional<MeterConfiguration> create(MeterConfigurationInput i){if(!valid(i))return Optional.empty(); var e=edges.ensure(i.clientId().trim(),i.siteId().trim(),i.edgeId().trim()); if(repository.uniqueKeyExistsForOtherMeter(e.id(),i.uniqueKey().trim(),null))return Optional.empty(); return Optional.of(repository.create(new MeterConfiguration(null,e.sitePk(),e.id(),e.clientId(),"",e.siteId(),"",e.edgeId(),i.uniqueKey().trim(),i.name().trim(),i.instantaneousAlarmOnKw(),i.instantaneousAlarmOffKw(),i.quarterHourAlarmOnKw(),i.quarterHourAlarmOffKw(),i.enabled(),0)));}
 public Optional<MeterConfiguration> update(Integer id,MeterConfigurationInput i){var current=repository.findById(id);if(id==null||current.isEmpty()||!valid(i))return Optional.empty();var e=edges.ensure(i.clientId().trim(),i.siteId().trim(),i.edgeId().trim());if(repository.uniqueKeyExistsForOtherMeter(e.id(),i.uniqueKey().trim(),id))return Optional.empty();return Optional.of(repository.update(new MeterConfiguration(id,e.sitePk(),e.id(),e.clientId(),"",e.siteId(),"",e.edgeId(),i.uniqueKey().trim(),i.name().trim(),i.instantaneousAlarmOnKw(),i.instantaneousAlarmOffKw(),i.quarterHourAlarmOnKw(),i.quarterHourAlarmOffKw(),i.enabled(),current.get().displayOrder())));}
 public boolean moveUp(Integer id){return id!=null&&repository.moveUp(id);} public boolean moveDown(Integer id){return id!=null&&repository.moveDown(id);} public boolean delete(Integer id){if(id==null||repository.findById(id).isEmpty())return false;repository.delete(id);return true;}
 private boolean valid(MeterConfigurationInput i){return i!=null&&text(i.clientId(),128)&&text(i.siteId(),128)&&text(i.edgeId(),128)&&text(i.uniqueKey(),128)&&text(i.name(),255)&&h(i.instantaneousAlarmOnKw(),i.instantaneousAlarmOffKw())&&h(i.quarterHourAlarmOnKw(),i.quarterHourAlarmOffKw());} private boolean text(String s,int max){return s!=null&&!s.trim().isEmpty()&&s.trim().length()<=max;} private boolean h(BigDecimal on,BigDecimal off){if(on==null&&off==null)return true;if(on==null||off==null)return false;return on.signum()>=0&&off.signum()>=0&&off.compareTo(on)<0;}
}
